insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-09', 't-growth', 2, 'التطبيق التربوي الصحيح لنظرية الذكاءات المتعددة:', '["تصنيف الطلاب في شعب حسب ذكاء واحد","تنويع الأنشطة ليجد كل طالب مدخلاً يناسب ذكاءه","إلغاء الاختبارات الكتابية نهائياً","تدريس الموهوبين فقط بها"]'::jsonb, 1, 'النظرية تدعو لتعدد مداخل التعلم وعرض المحتوى بطرائق متنوعة، لا لوصم الطلاب بنوع واحد.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-10', 't-growth', 2, 'طالب يذاكر حباً في الفهم والمعرفة دون انتظار مكافأة. دافعيته:', '["خارجية","داخلية","سلبية","اجتماعية"]'::jsonb, 1, 'الدافعية الداخلية تنبع من الرغبة الذاتية والاستمتاع بالتعلم، وهي أبقى أثراً من الخارجية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-11', 't-growth', 3, 'لإثارة دافعية طلاب منخفضي التحصيل، الأفضل أن يبدأ المعلم بـ:', '["مهام صعبة جداً لتحدي قدراتهم","مهام قصيرة قابلة للإنجاز تحقق نجاحات مبكرة","حرمانهم من الأنشطة حتى يتحسنوا","مقارنتهم بالمتفوقين باستمرار"]'::jsonb, 1, 'النجاحات الصغيرة المبكرة تبني الكفاءة الذاتية وتكسر توقع الفشل؛ والمقارنات السلبية تحطم الدافعية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-12', 't-growth', 2, 'من الممارسات الخاطئة في التعامل مع الدافعية:', '["ربط التعلم بحياة الطالب","التغذية الراجعة الفورية","التهديد المستمر بالاختبارات والعقوبات","تحديد أهداف واضحة قريبة"]'::jsonb, 2, 'التهديد يولد قلقاً معيقاً وارتباطاً انفعالياً سالباً بالمادة، وقد يدفع للغش أو التجنب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-13', 't-growth', 3, 'مبدأ صحيح من مبادئ النمو الإنساني:', '["النمو يسير بسرعة ثابتة في كل المراحل","تتأثر مظاهر النمو بالوراثة دون البيئة","النمو عملية مستمرة متدرجة تتفاوت سرعتها بين المراحل","مظاهر النمو مستقلة لا يؤثر بعضها في بعض"]'::jsonb, 2, 'النمو مستمر ومتدرج ومتفاوت السرعة، وتتفاعل فيه الوراثة والبيئة، ومظاهره متداخلة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tg-14', 't-growth', 2, 'لاحظت معلمة أن إحدى طالبات المرحلة المتوسطة انطوت فجأة وتدهور تحصيلها بشكل حاد ومستمر. التصرف السليم:', '["تجاهل الأمر لأنه سيزول","إحالتها للموجهة الطلابية مع متابعة الحالة","توبيخها لتحسين مستواها","إخبار الطالبات بمشكلتها ليساعدنها"]'::jsonb, 1, 'التغير الحاد المفاجئ مؤشر يستدعي تدخل المختص (الموجه الطلابي) مع الحفاظ على الخصوصية والمتابعة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-01', 't-planning', 1, 'الفائدة الأهم للتخطيط اليومي للدرس:', '["إرضاء المشرف التربوي","تنظيم عمل المعلم وتحديد وجهة التعلم وتقويمه","ملء السجلات الرسمية","إشغال وقت المعلم"]'::jsonb, 1, 'التخطيط يحدد الأهداف والإجراءات والتقويم، فيعطي الدرس اتجاهاً واضحاً — وليس غايةً شكلية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-02', 't-planning', 1, 'الترتيب الصحيح لمستويات الأهداف من الأعم إلى الأخص:', '["السلوكية ثم العامة ثم الغايات","الغايات ثم الأهداف العامة ثم الأهداف السلوكية","العامة ثم الغايات ثم السلوكية","السلوكية ثم الغايات ثم العامة"]'::jsonb, 1, 'الغايات أعم (مستوى الدولة)، تليها الأهداف العامة (المقرر)، ثم الخاصة/السلوكية (الدرس).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-03', 't-planning', 2, 'أي الصياغات الآتية هدف سلوكي صحيح؟', '["أن يعرف الطالب أهمية الصلاة","أن يشرح المعلم أركان الإسلام","أن يعدد الطالب ثلاثة من أركان الإسلام دون الرجوع للكتاب","تنمية حب المادة لدى الطلاب"]'::jsonb, 2, 'صياغة الهدف السلوكي: أن + فعل قابل للقياس + الطالب + المحتوى + المعيار. «يعرف» غير قابل للملاحظة، والهدف يصف سلوك المتعلم لا المعلم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-04', 't-planning', 2, 'الخطأ في الهدف: «أن يفهم الطالب قواعد السلامة ويطبقها في المختبر»:', '["ذكر الطالب","فعل غير قابل للقياس ودمج ناتجين في هدف واحد","تحديد مكان التطبيق","قابليته للقياس التام"]'::jsonb, 1, '«يفهم» فعل غير إجرائي، وجمع (يفهم ويطبق) يدمج ناتجين؛ والهدف الجيد يقيس ناتجاً واحداً بفعل ظاهر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-05', 't-planning', 1, 'الترتيب الصحيح لمستويات المجال المعرفي في تصنيف بلوم المعدل:', '["تذكر، فهم، تطبيق، تحليل، تقويم، إبداع","فهم، تذكر، تحليل، تطبيق، إبداع، تقويم","تذكر، تطبيق، فهم، تقويم، تحليل، إبداع","إبداع، تقويم، تحليل، تطبيق، فهم، تذكر"]'::jsonb, 0, 'يتدرج التصنيف المعدل من التذكر إلى الإبداع (بعد أن كان التقويم قمة التصنيف القديم).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-06', 't-planning', 2, '«أن يقارن الطالب بين التعلم التعاوني والتعلم الفردي من حيث الأدوار» — مستوى الهدف في تصنيف بلوم:', '["التذكر","الفهم","التطبيق","الإبداع"]'::jsonb, 1, 'المقارنة وبيان أوجه الشبه والاختلاف من أفعال مستوى الفهم (وقد ترقى للتحليل إذا تعمقت في العلاقات)؛ في صيغتها البسيطة هذه تصنف فهماً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-07', 't-planning', 2, '«أن يصمم الطالب تجربة جديدة لإثبات تمدد المعادن بالحرارة» — مستوى الهدف:', '["التطبيق","التحليل","الإبداع","التذكر"]'::jsonb, 2, 'التصميم والإنتاج الجديد قمة الهرم المعرفي (الإبداع).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-08', 't-planning', 2, '«أن يحل الطالب مسألة على مساحة المثلث باستخدام القانون» — مستوى الهدف:', '["التذكر","الفهم","التطبيق","التقويم"]'::jsonb, 2, 'استخدام قاعدة أو قانون في موقف جديد هو مستوى التطبيق.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-09', 't-planning', 2, '«أن يحكم الطالب على مقال ناقداً حججه بمعايير محددة» — مستوى الهدف:', '["الفهم","التقويم","التذكر","التطبيق"]'::jsonb, 1, 'إصدار الأحكام والنقد والتبرير وفق معايير هو مستوى التقويم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-10', 't-planning', 2, 'هدف «أن يقدّر الطالب جهود العلماء المسلمين» ينتمي إلى المجال:', '["المعرفي","الوجداني","النفس حركي","المهاري"]'::jsonb, 1, 'التقدير والاتجاهات والميول والقيم من المجال الوجداني (الانفعالي).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-11', 't-planning', 2, 'هدف «أن يرسم الطالب خريطة المملكة بدقة» ينتمي إلى المجال:', '["الوجداني","المعرفي","النفس حركي (المهاري)","الاجتماعي"]'::jsonb, 2, 'الرسم أداء عملي حركي منسق، فهو من المجال النفس حركي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-12', 't-planning', 1, 'النشاط الذي يبدأ به المعلم درسه لجذب الانتباه وربط الطلاب بالموضوع يسمى:', '["التقويم الختامي","التهيئة الحافزة","الواجب المنزلي","الغلق"]'::jsonb, 1, 'التهيئة مدخل مشوق (قصة، سؤال، صورة، موقف) يهيئ الطلاب نفسياً وذهنياً للدرس.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-13', 't-planning', 3, 'الوظيفة الأساسية لجدول المواصفات عند بناء الاختبار:', '["تسريع عملية التصحيح","ضمان صدق المحتوى وعدالة توزيع الأسئلة على الموضوعات والمستويات","تقليل عدد الأسئلة","رفع درجات الطلاب"]'::jsonb, 1, 'جدول المواصفات يربط الموضوعات بمستويات الأهداف وفق أوزانها النسبية، فيحقق صدق المحتوى والتمثيل العادل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-14', 't-planning', 2, 'عند بناء جدول المواصفات، يتحدد الوزن النسبي لكل موضوع بناءً على:', '["ترتيب الموضوع في الكتاب","عدد الحصص وأهمية الموضوع","سهولة صياغة أسئلته","رغبة الطلاب"]'::jsonb, 1, 'الوزن النسبي يعكس زمن تدريس الموضوع وأهميته النسبية في المقرر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-15', 't-planning', 2, 'عنصر خطة الدرس الذي يتحقق به المعلم من امتلاك الطلاب المتطلبات السابقة قبل البدء:', '["التقويم القبلي","التقويم الختامي","الواجب","الغلق"]'::jsonb, 0, 'التقويم القبلي يكشف المعرفة السابقة والمتطلبات اللازمة لبناء التعلم الجديد.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-16', 't-planning', 3, 'في نهاية الدرس لخص المعلم النقاط الأساسية وربطها بهدف الدرس وتأكد من تحققه. هذا الإجراء يسمى:', '["التهيئة","الغلق","العصف","الاستقصاء"]'::jsonb, 1, 'الغلق إنهاء منظم للدرس: تلخيص وربط وتثبيت لأبرز الأفكار والتحقق من تحقق الأهداف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-17', 't-planning', 2, 'عند صياغة أهداف درس لطلاب متفاوتي المستويات، الأفضل:', '["أهداف بمستوى واحد متوسط","تدرج الأهداف من الدنيا إلى العليا لتناسب الجميع","أهداف عليا فقط للتحدي","أهداف دنيا فقط لضمان النجاح"]'::jsonb, 1, 'تدرج الأهداف عبر مستويات بلوم يتيح لكل طالب النمو من مستواه، ويخدم التمايز.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('tp-18', 't-planning', 3, '«أن يستنتج الطالب العلاقة بين زاويتي المثلث وطول الضلع المقابل بعد فحص أمثلة متعددة» — مستوى الهدف:', '["التذكر","التحليل","التطبيق المباشر","الاستقبال"]'::jsonb, 1, 'استنتاج العلاقات بعد تفكيك الأمثلة وفحص المكونات من أفعال مستوى التحليل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-01', 't-strategies', 1, 'في التعلم النشط يكون دور المعلم الأساسي:', '["الملقّن الوحيد للمعرفة","الميسّر والموجّه لتعلم الطلاب","المتفرج على الأنشطة","المقوّم النهائي فقط"]'::jsonb, 1, 'التعلم النشط يجعل الطالب محور العملية والمعلم ميسراً يصمم الأنشطة ويوجه ويغذي راجعاً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-02', 't-strategies', 1, 'من القواعد الأساسية لجلسة العصف الذهني:', '["نقد الأفكار فور طرحها","تأجيل الحكم على الأفكار وتشجيع الكم","قصر المشاركة على المتفوقين","رفض الأفكار الغريبة"]'::jsonb, 1, 'إرجاء النقد، الترحيب بالغريب، الكم يولد الكيف، والبناء على أفكار الآخرين — قواعد العصف الأربع.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-03', 't-strategies', 2, 'عند تكوين مجموعات التعلم التعاوني، يفضل أن تكون المجموعات:', '["متجانسة في المستوى التحصيلي","غير متجانسة تجمع مستويات متفاوتة","حسب رغبات الطلاب دائماً","كبيرة العدد (10 فأكثر)"]'::jsonb, 1, 'عدم التجانس يتيح تبادل الدعم بين المستويات ويحقق أهداف التعاون، والحجم الأمثل 4–6.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-04', 't-strategies', 2, 'الفرق الجوهري بين التعلم التعاوني والعمل في مجموعات تقليدية:', '["عدد الطلاب فقط","وجود مسؤولية فردية وجماعية وأدوار محددة واعتماد متبادل إيجابي","مكان الجلوس","نوع المادة الدراسية"]'::jsonb, 1, 'التعاوني الحقيقي يقوم على الاعتماد الإيجابي المتبادل والمحاسبة الفردية والأدوار، لا مجرد جلوس جماعي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-05', 't-strategies', 2, 'معلم يريد تنمية مهارات التفكير العلمي بجعل طلابه يضعون الفروض ويختبرونها بالتجريب للوصول للمفهوم بأنفسهم. الاستراتيجية الأنسب:', '["المحاضرة","الاستقصاء","التسميع","العرض المباشر"]'::jsonb, 1, 'الاستقصاء يجعل المتعلم يمارس خطوات البحث العلمي ويكتشف المعرفة بنفسه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-06', 't-strategies', 2, 'الترتيب المنطقي لخطوات حل المشكلات:', '["فرض الفروض ثم الشعور بالمشكلة ثم التعميم","الشعور بالمشكلة ثم تحديدها ثم فرض الفروض ثم اختبارها ثم التعميم","اختبار الفروض ثم تحديد المشكلة","التعميم ثم جمع البيانات"]'::jsonb, 1, 'تبدأ بالشعور بالمشكلة وتحديدها، ثم جمع البيانات وفرض الفروض واختبارها، وتنتهي بالحل والتعميم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-07', 't-strategies', 2, 'كلف معلم طلابه بإنتاج مجسم لمدينة مستدامة يدمج مفاهيم العلوم والرياضيات والاجتماعيات على مدى شهر. الاستراتيجية:', '["التعلم بالمشاريع","التسميع الجماعي","المحاضرة المطولة","الإملاء المباشر"]'::jsonb, 0, 'التعلم بالمشاريع مهمة واقعية ممتدة تنتهي بمنتج وتدمج معارف ومهارات متعددة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-08', 't-strategies', 2, 'لتدريب الطلاب على مواقف اجتماعية كآداب الحوار ومساعدة الآخرين، الاستراتيجية الأنسب:', '["لعب الأدوار","حل المسائل","الاستذكار الفردي","الاختبارات القصيرة"]'::jsonb, 0, 'لعب الأدوار يجسد المواقف الحياتية ويتيح التدرب على المهارات الاجتماعية والاتجاهات في بيئة آمنة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-09', 't-strategies', 2, 'يرسل معلم فيديو الشرح قبل الحصة، ويخصص وقت الحصة للتطبيق وحل التدريبات ومناقشة الصعوبات. هذا يمثل:', '["الصف المقلوب","التعلم بالحفظ","المحاضرة التقليدية","التسميع"]'::jsonb, 0, 'الصف المقلوب: نقل الشرح للمنزل عبر الوسائط، وتحويل الحصة للتطبيق والتفاعل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-10', 't-strategies', 2, 'استراتيجية تنظم المفاهيم بصرياً من العام إلى الخاص وتظهر العلاقات بينها بكلمات رابطة:', '["خرائط المفاهيم","الكرسي الساخن","الرؤوس المرقمة","المراسل المتنقل"]'::jsonb, 0, 'خريطة المفاهيم تمثيل هرمي بصري للمفاهيم والعلاقات، تخدم التعلم ذا المعنى وتشخص الفهم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-11', 't-strategies', 3, 'قسّم معلم النص لأجزاء، وتخصص كل طالب في جزء ضمن «مجموعة خبراء»، ثم عاد كلٌّ لمجموعته الأصلية ليعلّم زملاءه جزأه. الاستراتيجية:', '["جيغسو (التعلم التشاركي)","العصف الذهني","الحوار السقراطي","التعلم بالاكتشاف"]'::jsonb, 0, 'جيغسو تقوم على مجموعات أصلية وخبراء، ويصبح كل طالب معلماً لجزئه — اعتماد إيجابي متبادل قوي.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-12', 't-strategies', 2, 'استراتيجية تضمن مشاركة كل طالب: تفكير فردي صامت، ثم مناقشة ثنائية، ثم مشاركة أمام الجميع:', '["فكر – زاوج – شارك","الاستقصاء الحر","التدريس المصغر","المحطات العلمية"]'::jsonb, 0, 'Think-Pair-Share تتيح زمن تفكير فردياً ثم تبادلاً ثنائياً قبل المشاركة الجماعية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-13', 't-strategies', 2, 'في بداية وحدة جديدة سأل المعلم: ماذا تعرفون عن الموضوع؟ وماذا تريدون معرفته؟ وفي نهايتها: ماذا تعلمتم؟ الاستراتيجية:', '["K-W-L (جدول التعلم)","الحقائب التعليمية","التعلم المبرمج","الأسئلة السابرة فقط"]'::jsonb, 0, 'جدول التعلم K-W-L يفعّل المعرفة السابقة ويحدد أهداف التعلم ثم يقوّم المكتسب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-14', 't-strategies', 2, 'من الممارسات الصحيحة في طرح الأسئلة الصفية:', '["تسمية الطالب قبل طرح السؤال","طرح السؤال للجميع ثم الانتظار ثوانٍ قبل اختيار المجيب","الاكتفاء بأسئلة التذكر","السخرية اللطيفة من الإجابات الخاطئة"]'::jsonb, 1, 'توجيه السؤال للجميع يبقي الكل منتبهاً، وزمن الانتظار (3–5 ثوانٍ) يحسّن جودة الإجابات وعمقها.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-15', 't-strategies', 3, 'أجاب طالب إجابة ناقصة، فقال المعلم: «إجابة جيدة كبداية، من يضيف عليها؟ وماذا لو غيّرنا الشرط؟». هذا النوع من الأسئلة يسمى:', '["الأسئلة السابرة","الأسئلة المغلقة","أسئلة الترديد","الأسئلة الإيحائية"]'::jsonb, 0, 'السبر يتعمق في إجابة الطالب بأسئلة متتابعة للتوسيع أو التوضيح أو إعادة التوجيه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-16', 't-strategies', 2, 'المعيار الأهم لاختيار استراتيجية التدريس:', '["حداثة الاستراتيجية وشهرتها","ملاءمتها للأهداف والمحتوى وخصائص المتعلمين والإمكانات","سهولتها على المعلم","إعجاب المشرف بها"]'::jsonb, 1, 'لا توجد استراتيجية مثلى مطلقاً؛ الملاءمة للهدف والمحتوى والطلاب والإمكانات هي الفيصل.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-17', 't-strategies', 2, 'لتعليم مهارة الوضوء عملياً لطلاب الصف الأول، الأنسب أن يبدأ المعلم بـ:', '["شرح نظري مطول","عرض نموذجي عملي أمام الطلاب ثم محاكاتهم له بتغذية راجعة","اختبار تحريري","واجب منزلي"]'::jsonb, 1, 'المهارات الأدائية تعلم بالنمذجة العملية ثم الممارسة الموجهة بتغذية راجعة فورية.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-18', 't-strategies', 3, 'لاحظ معلم أن طلابه يحفظون القاعدة دون قدرة على توظيفها في مواقف جديدة. أفضل معالجة:', '["زيادة التسميع والتكرار","تقديم مواقف وتطبيقات متنوعة وسياقات حياتية لنقل أثر التعلم","إعادة شرح القاعدة بالطريقة نفسها","حذف القاعدة من الاختبار"]'::jsonb, 1, 'انتقال أثر التعلم يتطلب تطبيقاً في سياقات متعددة وواقعية، لا مزيداً من الحفظ الصم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-19', 't-strategies', 2, 'استراتيجية يجلس فيها طالب أمام زملائه ليطرحوا عليه أسئلة حول موضوع أو شخصية يمثلها:', '["الكرسي الساخن","جدول التعلم","النصوص المتقابلة","البطاقات المروحية"]'::jsonb, 0, 'الكرسي الساخن ينمي الطلاقة اللغوية والثقة وعمق الفهم عبر أسئلة الزملاء المتلاحقة.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ts-20', 't-strategies', 3, 'في التدريس التبادلي لتنمية الفهم القرائي، يتبادل الطلاب أدواراً أبرزها:', '["القائد والحارس والمهرج","المتنبئ والمتسائل والموضح والملخص","الكاتب والرسام","المصحح والمراقب فقط"]'::jsonb, 1, 'أدوار التدريس التبادلي الأربعة: التنبؤ، التساؤل، التوضيح، التلخيص — تُنمّي مراقبة الفهم.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('ta-01', 't-assessment', 1, 'إعطاء درجة رقمية لأداء الطالب في اختبار دون إصدار حكم يسمى:', '["تقويماً","قياساً","تشخيصاً","علاجاً"]'::jsonb, 1, 'القياس تكميم السمة بالأرقام، والتقويم أشمل: يتضمن الحكم والتحسين.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
